        {"대지":"서론", "내용":"순찰대의 보고는 놀라웠다. '온 땅이 평안하여 정온하더이다.' 좋은 소식처럼 들리지만, 이것은 이스라엘에게 고통스러운 보고였다. 자신들을 억압한 나라들이 아무 심판 없이 잘 지내고 있다니. 왜 악인은 평안하고 의인은 고통받는가", "예화_적용":"왜 나쁜 사람이 잘 되고 착한 사람이 힘든가 — 오래된 질문"},
        {"대지":"1대지: 온 땅이 평안하여 (열방의 안일)", "내용":"이스라엘을 억압한 나라들이 편안히 앉아 있음. 공의가 이루어지지 않은 것처럼 보이는 현실", "예화_적용":"불의한 자가 잘 되는 것 같은 현실에 낙심하지 말라"},
        {"대지":"2대지: 정온하더이다 (이스라엘의 답답함)", "내용":"열방은 정온하지만 이스라엘은 여전히 속국. 성전 재건도 미완. 약속의 성취가 지연되는 답답함", "예화_적용":"약속이 지연되는 것 같을 때가 가장 힘든 시간이다"},
        {"대지":"3대지: 여호와의 사자에게 고하되 (하나님은 아신다)", "내용":"보고가 하나님의 사자에게 전해짐. 하나님은 이 상황을 정확히 알고 계신다", "예화_적용":"하나님은 불공평해 보이는 상황을 모르시는 것이 아니다. 때가 되면 행동하신다"},
        {"대지":"결론", "내용":"다음 절에서 여호와의 사자가 이스라엘을 위해 중보하신다. 세상이 평안해 보여도 하나님은 자기 백성을 잊지 않으신다. 악인의 평안은 일시적이고 하나님의 공의는 영원하다. 인내하며 기다리자", "예화_적용":"하나님의 시간표를 신뢰하라. 공의는 반드시 이루어진다"}
