        {"항목":"예루살렘을 헤친 뿔", "내용":"예루살렘 성전과 성벽이 바벨론에 의해 파괴됨(BC 586). 하나님의 임재의 상징이 무너진 충격", "목회적활용":"가장 거룩한 것도 불순종의 결과를 피하지 못하지만 하나님은 회복하신다"}
