    표5_매튜헨리: [
        {"영어원문":"These are the horns which have scattered Judah, Israel, and Jerusalem — no part of God's people escaped their fury.", "한국어번역":"이들은 유다와 이스라엘과 예루살렘을 흩은 뿔이니 하나님의 백성 중 그 분노를 피한 곳이 없다.", "핵심통찰":"하나님의 백성 전체가 겪은 고난의 보편성"},
        {"영어원문":"The prophet asks, and the angel answers — this is the way to understand divine visions, by humble inquiry.", "한국어번역":"선지자가 묻고 천사가 답하니 이것이 신적 환상을 이해하는 방법이니 겸손한 질문이다.", "핵심통찰":"겸손한 질문이 영적 이해의 열쇠"},
        {"영어원문":"God took notice of every horn that pushed His people, and He will reckon with them all.", "한국어번역":"하나님은 백성을 받은 모든 뿔을 주목하셨으며 그 모두에게 청산하실 것이다.", "핵심통찰":"하나님은 모든 공격을 기억하시고 갚으신다"}
    ],
