        {"대지":"2대지: 기뻐하라 (기쁨의 명령)", "내용":"환경이 아닌 하나님의 약속에 근거한 기쁨. 어려운 현실 속에서도 가능한 기쁨", "예화_적용":"감옥에서도 찬송한 바울과 실라처럼 하나님의 임재가 있으면 기쁨이 있다"},
        {"대지":"3대지: 네 가운데 거하리라 (임재의 약속)", "내용":"'샤칸(장막을 치다)'은 영구적 거하심. 하나님이 우리 삶에 장막을 치시는 영광", "예화_적용":"왕이 백성의 동네에 와서 거하시듯 하나님이 우리 가운데 오신다"},
        {"대지":"결론", "내용":"하나님이 오신다. 우리 가운데 거하신다. 이것이 기독교의 핵심이요 기쁨의 원천이다. 시온의 딸아, 노래하고 기뻐하라!", "예화_적용":"크리스마스의 기쁨이 바로 이것이다 - 하나님이 우리 가운데 오신 것"}
