        {"상황":"하나님이 행동하시지 않는 것 같아 답답한 분", "성경원리":"하나님이 성소에서 일어나신다. 일어나시기 전의 침묵은 행동 직전의 준비", "실제적용":"하나님의 침묵이 무관심이 아니다. 일어나실 때를 기다리라"},
        {"상황":"경외심을 회복하고 싶은 분", "성경원리":"하나님 앞에서의 침묵은 가장 깊은 경외의 표현", "실제적용":"예배 중 침묵의 시간을 가지라. 하나님의 위엄을 묵상하며 잠잠히 기다리라"}
