        {"구절":"계 19:11", "연결점":"하늘이 열린 것을 보니 백마를 탄 이가 있으니 충신과 진실이라 칭하더라", "구분":"신약"},
        {"구절":"롬 3:19", "연결점":"온 세상으로 하나님의 심판 아래에 있게 하려 함이라", "구분":"신약"}
