        {"상황":"교회가 빛을 잃고 있다고 느끼는 분", "성경원리":"등대의 빛은 기름(성령)의 공급에 달려 있다. 관이 막히면 빛이 꺼진다", "실제적용":"교회의 빛은 프로그램이 아닌 성령의 역사에서 온다. 성령을 구하라"},
        {"상황":"하나님의 공급이 부족하다고 느끼는 분", "성경원리":"일곱 등잔에 일곱 관. 49개의 공급로. 하나님의 공급은 완벽하고 풍성", "실제적용":"하나님의 공급은 항상 충분하다. 공급이 부족한 것이 아니라 받는 통로를 점검하라"}
