        {"항목":"등대 좌우", "내용":"등대 양쪽에 있는 감람나무의 위치와 역할에 대한 구체적 질문", "목회적활용":"영적 사물의 배치와 구조에도 의미가 있다"},
        {"항목":"끈질긴 탐구", "내용":"이미 한 번 질문했으나 충분한 답을 얻지 못해 다시 묻는다. 포기하지 않는 탐구 정신", "목회적활용":"이해될 때까지 묻고 또 물으라"}
