    표6_설교자료: [
        {"대지":"제목", "내용":"다시 묻는 스가랴 - 끈질긴 영적 탐구", "예화_적용":"이해될 때까지 질문하는 것이 진정한 배움"},
        {"대지":"서론", "내용":"스가랴가 다시 묻는다. 이미 한 번 물었는데 또 묻는다. 왜? 아직 충분히 이해하지 못했기 때문이다. 이 끈질긴 탐구 정신이 14절의 놀라운 답을 이끌어낸다", "예화_적용":"에디슨이 만 번의 실패 후에도 포기하지 않았듯"},
        {"대지":"1대지: 다시 묻다 (포기하지 않는 탐구)", "내용":"한 번의 질문으로 만족하지 않고 다시 묻는다. 영적 진리에 대한 갈증", "예화_적용":"한 번 읽어서 이해 안 되면 열 번 읽는 학생이 최고의 학생"},
        {"대지":"2대지: 무슨 뜻이니이까 (의미의 추구)", "내용":"단순히 보는 것에 그치지 않고 의미를 물음. 표면을 넘어 깊이를 추구", "예화_적용":"미술관에서 그림을 보고 넘기는 사람과 작가의 의도를 탐구하는 사람의 차이"},
        {"대지":"3대지: 등대 좌우의 감람나무 (구체적 질문)", "내용":"추상적이지 않고 구체적으로 묻는다. 좋은 질문은 구체적이다", "예화_적용":"좋은 질문은 좋은 답의 절반이다"},
        {"대지":"결론", "내용":"하나님의 말씀을 읽을 때 한 번에 이해되지 않으면 다시 묻고 다시 묵상하라. 끈질긴 탐구가 더 깊은 계시로 이끈다. 포기하지 말고 구하라", "예화_적용":"광부가 깊이 팔수록 더 귀한 광석을 만나듯 깊이 탐구할수록 귀한 진리를 만난다"}
    ],
