        {"교리":"죄의 보편성", "설명":"온 땅에서 그들의 모양이 이러하다는 것은 죄가 모든 인류에게 보편적임을 보여줌", "관련구절":"롬 3:23, 롬 5:12, 전 7:20, 시 14:3"},
        {"교리":"물질주의와 악", "설명":"상업적 측량 도구인 에바가 악의 그릇이 되는 것은 물질주의가 악의 통로가 될 수 있음을 상징", "관련구절":"딤전 6:10, 마 6:24, 약 5:1-3, 눅 12:15"}
