        {"항목":"집을 지음", "내용":"악을 위한 집(바이트)은 신전의 의미도 있음. 바벨론에서 악이 우상으로 숭배됨을 암시. 악이 하나님의 땅에서 제거되어 이방 땅에 갇힘", "목회적활용":"하나님의 영역에서 악이 완전히 제거되어 격리됨"},
        {"항목":"준공과 안치", "내용":"건축이 완료되면 악이 영구적으로 그곳에 머문다. 이는 악의 최종적이고 영구적인 격리를 의미", "목회적활용":"하나님의 심판의 최종 결과는 악의 영구적 격리이다"}
