    표5_매튜헨리: [
        {"영어원문":"Four chariots came out from between two mountains of brass, representing God's irresistible judgments.", "한국어번역":"네 병거가 두 놋산 사이에서 나왔으니 이는 하나님의 불가항력적 심판을 나타낸다.", "핵심통찰":"하나님의 심판은 어떤 세력도 막을 수 없다"},
        {"영어원문":"The mountains of brass signify the immovable decrees of God upon which His judgments are founded.", "한국어번역":"놋산은 하나님의 심판이 기초한 바 움직일 수 없는 하나님의 작정을 상징한다.", "핵심통찰":"하나님의 작정은 놋처럼 견고하여 변하지 않는다"},
        {"영어원문":"This last vision answers to the first, completing the cycle of God's providential dealings with the nations.", "한국어번역":"이 마지막 환상은 첫 환상에 대응하여 열국을 향한 하나님의 섭리적 경륜의 순환을 완성한다.", "핵심통찰":"하나님의 경륜은 완전한 순환 구조를 이룬다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"놋산 사이의 네 병거 - 견고한 심판의 출발", "예화_적용":"하나님의 심판은 놋처럼 견고한 기초 위에 서 있다"},
        {"대지":"서론", "내용":"스가랴의 마지막 밤 환상이 시작된다. 두 놋산 사이에서 네 병거가 나온다. 첫 환상에서 세상을 순찰하던 말들이 이제 심판을 집행하는 병거로 돌아왔다. 하나님의 계획은 정찰에서 심판으로, 관찰에서 행동으로 전진한다", "예화_적용":"하나님은 모든 것을 아시고 때가 되면 반드시 행동하신다"},
        {"대지":"1대지: 두 놋산 (견고한 심판의 기초)", "내용":"놋은 심판을 상징하는 금속. 두 놋산은 하나님의 심판이 흔들리지 않는 견고한 기초 위에 있음을 보여줌", "예화_적용":"인간의 법정은 흔들리지만 하나님의 법정은 놋처럼 견고하다"},
        {"대지":"2대지: 네 병거 (사방의 심판)", "내용":"네 병거가 사방으로 나가는 것은 하나님의 심판이 온 세계에 미침을 보여줌. 피할 곳이 없다", "예화_적용":"지구 어느 곳에도 하나님의 통치를 벗어난 곳은 없다"},
        {"대지":"3대지: 산 사이에서 나옴 (심판의 출발)", "내용":"병거가 산 사이에서 나오는 것은 하나님의 임재에서 심판이 시작됨을 보여줌", "예화_적용":"심판은 하나님의 보좌에서 시작된다"},
        {"대지":"결론", "내용":"마지막 환상의 네 병거는 하나님의 심판이 확실히 집행됨을 보여준다. 하나님의 정의는 놋처럼 견고하고 그 집행은 병거처럼 강력하다. 이 하나님을 경외하며 살라", "예화_적용":"심판의 하나님을 경외하는 것이 지혜의 시작이다"}
    ],
