        {"항목":"모셨다가 나감", "내용":"병거들이 하나님 앞에 서 있다가 명령을 받고 나가는 구조. 천상 회의의 장면을 보여줌 (욥 1:6, 왕상 22:19)", "목회적활용":"하나님의 모든 도구는 명령 아래 행동한다"}
