        {"항목":"순찰의 의미", "내용":"히트할레크(두루 다니다)는 에덴동산에서 하나님이 거니신 것(창 3:8)과 같은 동사. 하나님의 임재가 온 땅에 미침을 상징", "목회적활용":"하나님의 임재는 온 세상에 미치며 숨을 곳이 없다"}
