        {"대지":"서론", "내용":"은과 금으로 면류관을 만들어 대제사장 여호수아에게 씌운다. 이것은 전례 없는 행위였다. 제사장은 면류관이 아니라 관을 쓰고 왕만이 면류관을 썼다. 이 파격은 장차 오실 메시아 그리스도를 가리킨다", "예화_적용":"인류 역사상 유일하게 왕이면서 제사장인 분은 예수 그리스도뿐이시다"},
        {"대지":"1대지: 은과 금으로 (구속과 영광)", "내용":"은은 속량의 가치를, 금은 왕권의 영광을 상징. 그리스도는 구속과 영광을 모두 가지신 분", "예화_적용":"십자가의 고난(은)이 부활의 영광(금)으로 이어진다"},
        {"대지":"2대지: 면류관을 만들어 (왕관의 제작)", "내용":"히브리어 아타로트는 복수형. 여러 겹의 면류관으로 그리스도의 다중적 주권을 상징", "예화_적용":"그리스도의 머리에는 많은 면류관이 있다 (계 19:12)"},
        {"대지":"3대지: 대제사장 여호수아에게 (제사장-왕)", "내용":"대제사장에게 왕관을 씌움은 제사장직과 왕직의 결합. 멜기세덱의 반차를 따르는 메시아 예표", "예화_적용":"예수님은 우리를 위해 중보하시는 제사장이며 우리를 다스리시는 왕이시다"},
        {"대지":"결론", "내용":"면류관을 쓴 대제사장 여호수아는 그리스도의 살아있는 예표이다. 가시면류관을 쓰신 그 분이 영광의 면류관을 쓰실 것이다. 이 왕이시며 제사장이신 분을 경배하라", "예화_적용":"가시면류관의 수치가 영광의 면류관으로 바뀌셨다"}
