    표5_매튜헨리: [
        {"영어원문":"The word of the Lord came to Zechariah, in answer to the enquiry that was made, but it went much further than the question.", "한국어번역":"여호와의 말씀이 질문에 대한 응답으로 스가랴에게 임했으나 그 답은 질문보다 훨씬 깊이 나아갔다.", "핵심통찰":"하나님의 답은 우리의 질문보다 항상 깊다"},
        {"영어원문":"God did not only answer their question about fasting, but took this occasion to lay before them the great things which he required.", "한국어번역":"하나님은 금식에 관한 질문에만 답하신 것이 아니라 이 기회를 빌려 그가 요구하시는 큰 것들을 앞에 놓으셨다.", "핵심통찰":"하나님은 작은 질문을 통해 큰 교훈을 주신다"},
        {"영어원문":"The word of the Lord of hosts—what a weight there is in that! It commands attention and demands obedience.", "한국어번역":"만군의 여호와의 말씀 - 이 표현에 얼마나 큰 무게가 있는가! 주목을 명하고 순종을 요구한다.", "핵심통찰":"만군의 여호와의 말씀은 절대적 권위를 가진다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"만군의 여호와의 말씀이 임하니라 - 하나님의 응답", "예화_적용":"하나님은 우리의 질문에 침묵하지 않으시고 말씀으로 응답하신다"},
        {"대지":"서론", "내용":"벧엘 사절단이 금식에 대해 물었다. 그들은 '예' 또는 '아니오'라는 간단한 답을 기대했을 것이다. 그러나 만군의 여호와는 그들의 질문보다 훨씬 깊은 차원에서 답하셨다", "예화_적용":"하나님의 답은 항상 우리의 기대를 초월한다"},
        {"대지":"1대지: 만군의 여호와 (절대적 권위)", "내용":"'만군의 여호와'라는 칭호는 이 말씀의 절대적 권위를 선언. 하늘의 군대를 지휘하시는 분이 말씀하신다", "예화_적용":"하나님의 말씀 앞에서 겸손히 귀를 기울여야 한다"},
        {"대지":"2대지: 말씀이 임하여 (계시의 주도권)", "내용":"말씀이 '임한다'는 것은 계시의 주도권이 하나님께 있음을 의미. 인간이 구한 것에 대해 하나님이 주권적으로 응답하심", "예화_적용":"기도의 응답은 하나님의 때와 방식에 따른다"},
        {"대지":"3대지: 이르시되 (구체적 내용)", "내용":"하나님의 말씀은 막연하지 않고 구체적 내용을 가진다. 금식의 본질, 과거의 교훈, 미래의 약속이 담김", "예화_적용":"하나님의 말씀은 우리 삶에 구체적 방향을 제시한다"},
        {"대지":"결론", "내용":"만군의 여호와가 말씀하신다. 이 사실 앞에서 우리가 할 일은 하나 - 귀를 열고 순종하는 것이다. 하나님은 오늘도 말씀하고 계신다", "예화_적용":"하나님의 말씀에 귀를 열고 삶으로 순종하라"}
    ],
