        {"새찬송가":"234", "통일찬송가":"225", "제목":"주의 말씀 따라서", "선정이유":"만군의 여호와의 말씀을 따르는 삶"},
        {"새찬송가":"541", "통일찬송가":"252", "제목":"날 대로 살게 하소서", "선정이유":"하나님의 말씀대로 사는 삶의 헌신"}
