        {"원어":"שְׁלֵוָה (쉘레바)", "의미_문법":"형통/평안 - 명사. 안전하고 번영하는 상태", "설교포인트":"형통할 때 하나님의 말씀을 무시하면 형통을 잃게 된다"},
        {"원어":"הַנֶּגֶב וְהַשְּׁפֵלָה (한네게브 웨핫쉐펠라)", "의미_문법":"남방과 평원 - 고유명사. 유다의 남쪽과 서쪽 저지대", "설교포인트":"온 땅에 사람이 거하는 형통함이 하나님의 뜻이었다"}
