    표5_매튜헨리: [
        {"영어원문":"Should you not hear the words which the Lord cried by the former prophets? They had warning enough, but they would not take it.", "한국어번역":"여호와가 이전 선지자로 외친 말을 너희가 듣지 않겠느냐? 그들은 충분한 경고를 받았으나 듣지 않았다.", "핵심통찰":"충분한 경고를 무시한 것이 심판의 원인"},
        {"영어원문":"Jerusalem was then inhabited and in prosperity. They had wealth and peace, and yet they would not hear.", "한국어번역":"예루살렘이 그때 거주민이 있고 형통하였다. 부요함과 평화가 있었으나 그들은 듣지 않았다.", "핵심통찰":"형통한 때 하나님의 말씀을 무시하는 것이 가장 위험"},
        {"영어원문":"Let the present generation take warning by the judgments God brought upon their fathers for their disobedience.", "한국어번역":"지금 세대가 불순종으로 인해 조상들에게 내린 심판을 교훈으로 삼으라.", "핵심통찰":"역사의 교훈을 통해 현재를 바로잡아야 한다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"이전 선지자로 외친 말 - 역사로부터 배우라", "예화_적용":"과거의 실수를 반복하지 않는 것이 지혜이다"},
        {"대지":"서론", "내용":"하나님은 금식 질문에 답하시면서 역사를 돌아보게 하신다. 형통하던 시절에 선지자들이 외쳤으나 듣지 않았고, 그 결과 포로의 비극이 왔다. 같은 실수를 반복하지 말라는 경고", "예화_적용":"역사를 모르는 자는 역사를 반복한다는 말이 신앙에도 적용된다"},
        {"대지":"1대지: 이전 선지자로 외침 (일관된 하나님의 메시지)", "내용":"이사야, 예레미야, 미가 등 이전 선지자들이 같은 메시지를 외침. 하나님의 요구는 시대를 초월하여 동일", "예화_적용":"하나님의 말씀은 변하지 않는다. 시대가 달라도 핵심은 같다"},
        {"대지":"2대지: 형통하였고 (축복의 시절)", "내용":"예루살렘과 남방과 평원까지 사람이 거하는 형통한 때. 하나님의 축복이 넘쳤던 시절", "예화_적용":"형통할 때가 가장 위험하다. 축복 속에서 말씀을 잊기 쉽다"},
        {"대지":"3대지: 청종할 것이 아니냐 (결단의 촉구)", "내용":"과거의 교훈을 바탕으로 지금 결단할 것을 촉구. 같은 실수를 반복하지 말라", "예화_적용":"들은 것을 행하는 자가 복이 있다. 지금이 결단할 때이다"},
        {"대지":"결론", "내용":"이전 선지자들의 외침은 오늘 우리에게도 유효하다. 형통할 때 하나님의 말씀에 귀를 기울이고, 역사의 교훈을 기억하며, 정의와 긍휼을 행하라", "예화_적용":"과거의 교훈을 기억하고 오늘을 바르게 사는 것이 참된 지혜이다"}
    ],
