        {"새찬송가":"241", "통일찬송가":"196", "제목":"나의 갈 길 멀고", "선정이유":"하나님의 인도를 따라 걸어가는 신앙의 여정"},
        {"새찬송가":"543", "통일찬송가":"455", "제목":"주 뜻대로 행하소서", "선정이유":"하나님의 뜻에 청종하여 순종하는 삶"}
