        {"대지":"2대지: 등으로 향하며 (관계 거부)", "내용":"고집 센 소가 멍에를 벗으려고 등을 돌리듯, 하나님의 인도를 완전히 거부", "예화_적용":"하나님을 등진다는 것은 축복의 근원을 등지는 것이다. 돌아서라"},
        {"대지":"3대지: 귀를 막으며 (완전한 차단)", "내용":"의도적으로 귀를 무겁게 하여 하나님의 음성을 완전히 차단. 불순종의 최종 단계", "예화_적용":"영적 귀머거리가 되기 전에 하나님의 음성에 귀를 열라"},
        {"대지":"결론", "내용":"불순종은 점진적이다. 오늘 작은 무시가 내일 큰 반항이 된다. 지금 귀를 열고 하나님의 말씀을 들으라. 아직 들을 수 있을 때 들으라", "예화_적용":"지금이 하나님의 음성을 듣고 돌이킬 수 있는 은혜의 때이다 (고후 6:2)"}
