        {"원어":"בְּרוּחוֹ (브루호)", "의미_문법":"그의 영(신)으로 - 명사+접미. 하나님의 영, 성령", "설교포인트":"선지자들은 하나님의 영으로 말했기에 그 말을 거부하는 것은 성령을 거부하는 것"},
        {"원어":"קֶצֶף גָּדוֹל (게체프 가돌)", "의미_문법":"큰 노(진노) - 명사+형용사. 넘치는 분노, 폭발적 심판", "설교포인트":"반복된 불순종에 대한 하나님의 진노는 반드시 임한다"}
