        {"교리":"기도 응답의 조건", "설명":"하나님의 응답은 무조건적이 아니다. 평소에 하나님의 부르심에 응하는 자가 위기에도 응답받는다", "관련구절":"시 66:18, 사 59:1-2, 요일 3:22, 약 5:16"},
        {"교리":"하나님의 공의", "설명":"하나님의 침묵은 잔인함이 아니라 공의의 표현. 은혜를 반복적으로 거부한 것에 대한 정당한 결과", "관련구절":"갈 6:7, 롬 2:6, 호 8:7, 욥 27:8-9"}
