        {"대지":"서론", "내용":"하나님이 시온에 돌아오신다. 이것이 8장 모든 축복의 기초이다. 하나님의 임재가 회복되면 예루살렘은 진리의 성읍이 되고 시온산은 성산이 된다. 임재가 모든 것을 변화시킨다", "예화_적용":"하나님의 임재가 있으면 황폐한 곳도 거룩한 곳으로 변한다"},
        {"대지":"1대지: 시온에 돌아옴 (임재의 회복)", "내용":"하나님이 심판으로 떠나셨다가 다시 돌아오시겠다는 선언. 가장 근본적인 회복", "예화_적용":"모든 회복의 시작은 하나님의 임재의 회복이다. 그분의 임재를 사모하라"},
        {"대지":"2대지: 진리의 성읍 (성품의 변화)", "내용":"하나님이 거하시면 도시의 성품이 변한다. 거짓이 물러가고 진리가 지배", "예화_적용":"하나님의 임재가 가정을, 직장을, 교회를 진리의 공동체로 변화시킨다"},
        {"대지":"3대지: 성산 (거룩함의 회복)", "내용":"하나님의 임재가 산을 성산으로 만드심. 더럽혀진 것이 거룩하게 됨", "예화_적용":"하나님의 임재 앞에서 우리의 더러움이 정결하게 된다"},
        {"대지":"결론", "내용":"하나님의 임재가 모든 것을 변화시킨다. 진리와 거룩함은 하나님의 임재의 자연스러운 결과이다. 오늘 하나님의 임재를 사모하고 초청하라", "예화_적용":"임마누엘 - 하나님이 우리와 함께 하시면 모든 것이 새로워진다"}
