        {"영어원문":"It intimates that the city shall enjoy a profound peace and tranquillity, such as is agreeable to the temper and spirit of old people.", "한국어번역":"이는 그 도시가 노인의 기질과 정신에 합당한 깊은 평화와 평온을 누릴 것임을 암시한다.", "핵심통찰":"참된 평화는 가장 연약한 자도 안전한 상태"},
        {"영어원문":"There shall be no war to cut them off, no plague to shorten their days.", "한국어번역":"그들을 끊어낼 전쟁도 없고 그들의 날을 단축할 역병도 없을 것이다.", "핵심통찰":"하나님의 보호 아래 생명이 보전됨"}
