    표6_설교자료: [
        {"대지":"제목", "내용":"예루살렘 길거리의 노인들 - 일상 속의 하나님 나라", "예화_적용":"하나님 나라의 축복은 거창한 것이 아니라 평범한 일상의 평화 속에 있다"},
        {"대지":"서론", "내용":"하나님이 그리시는 회복의 첫 장면은 놀랍게도 평범하다. 예루살렘 길거리에 노인들이 지팡이를 짚고 앉아 있는 모습이다. 화려한 성전도, 강력한 군대도 아닌 노인의 평안한 모습이 하나님 나라의 증거라니!", "예화_적용":"하나님의 축복은 화려함 속이 아니라 평범한 일상의 평안함 속에 있다"},
        {"대지":"1대지: 늙은 지아비와 지어미 (생명의 보존)", "내용":"전쟁과 역병으로 노인이 사라졌던 도시에 다시 노인이 거함. 생명이 보존되는 축복", "예화_적용":"노인이 함께하는 것은 세대의 연속성과 하나님의 보호의 표징이다"},
        {"대지":"2대지: 길거리에 앉음 (공공의 안전)", "내용":"공공장소에서 노인이 안전하게 앉을 수 있는 것은 사회의 안정과 평화의 증거", "예화_적용":"가장 연약한 자가 안전한 사회가 하나님이 축복하신 사회이다"},
        {"대지":"3대지: 지팡이를 잡음 (장수의 축복)", "내용":"지팡이가 필요할 만큼 오래 사는 것. 구약에서 장수는 하나님의 축복의 대표적 표현", "예화_적용":"하루하루 살아 있음에 감사하라. 생명 자체가 하나님의 축복이다"},
        {"대지":"결론", "내용":"하나님 나라의 비전은 노인이 평안히 쉬고 아이들이 뛰노는 평화로운 일상이다. 이것이 하나님이 우리에게 약속하시는 축복이다", "예화_적용":"오늘의 평범한 일상 속에서 하나님의 축복을 발견하라"}
    ],
