        {"구절":"계 21:4", "연결점":"다시는 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 다시 있지 아니하리니", "구분":"신약"},
        {"구절":"요 10:10", "연결점":"내가 온 것은 양으로 생명을 얻게 하고 더 풍성히 얻게 하려는 것이라", "구분":"신약"}
