        {"대지":"서론", "내용":"4절의 노인에 이어 5절은 아이들이 등장한다. 텅 비었던 예루살렘 거리에 아이들이 가득하여 뛰노는 모습. 이것이 하나님이 그리시는 회복의 두 번째 장면이다. 노인의 안식과 아이들의 놀이가 함께하는 완전한 평화", "예화_적용":"아이들이 안심하고 뛰놀 수 있는 세상이 하나님이 원하시는 세상이다"},
        {"대지":"1대지: 동남과 동녀 (다음 세대의 풍성함)", "내용":"소년과 소녀가 가득하다는 것은 다음 세대가 풍성하게 자라남을 의미. 공동체의 미래가 보장됨", "예화_적용":"다음 세대를 귀히 여기고 양육하는 것이 공동체의 가장 중요한 사명"},
        {"대지":"2대지: 거리에 가득하여 (생명의 충만)", "내용":"텅 빈 폐허의 거리가 아이들로 가득 찬 놀이터로 변함. 죽음의 자리가 생명으로 채워짐", "예화_적용":"하나님은 죽음의 현장을 생명으로 채우시는 분이다"},
        {"대지":"3대지: 장난하리라 (순수한 기쁨)", "내용":"아이들의 놀이는 순수한 기쁨의 표현. 근심과 공포가 아닌 기쁨이 넘치는 공동체", "예화_적용":"신앙 공동체는 기쁨이 넘치는 곳이어야 한다"},
        {"대지":"결론", "내용":"하나님이 그리시는 회복된 예루살렘에는 노인의 안식과 아이들의 기쁨이 함께한다. 이것이 하나님 나라의 모습이다. 우리의 가정, 교회, 사회가 이런 곳이 되도록 기도하고 실천하자", "예화_적용":"모든 세대가 함께 웃고 기뻐하는 공동체를 만들어가자"}
