        {"항목":"외부 위협", "내용":"사마리아인과 주변 민족의 방해로 출입이 평안치 못함(스 4:1-5). 외적 위협이 일상을 위협", "목회적활용":"하나님의 보호 없이는 일상의 안전도 보장되지 않는다"},
        {"항목":"내부 갈등", "내용":"'서로 치게 하였음'은 공동체 내부의 분열과 갈등. 외적 위협뿐 아니라 내적 불화까지 겪음", "목회적활용":"하나님의 축복이 떠나면 공동체 내부도 무너진다"}
