        {"새찬송가":"380", "통일찬송가":"285", "제목":"구주의 십자가 보혈로", "선정이유":"죄로 인한 고통에서 구원하신 보혈의 은혜"},
        {"새찬송가":"453", "통일찬송가":"365", "제목":"내 갈 길 멀고", "선정이유":"어려운 시절을 지나 하나님의 인도를 경험"}
