        {"원어":"תֶּחֱזַקְנָה יְדֵיכֶם (테헤즈카나 예데이켐)", "의미_문법":"손을 견고히 하라 - 동사+명사. 용기를 내어 힘쓰라", "설교포인트":"축복의 약속은 담대한 실천을 촉구한다"}
