        {"항목":"유다와 이스라엘", "내용":"남왕국(유다)과 북왕국(이스라엘) 모두를 포함하는 호칭. 분열된 민족의 통합된 회복을 약속", "목회적활용":"하나님의 회복은 분열을 넘어 통합을 이루신다"},
        {"항목":"두려워 말라", "내용":"주변 열국의 위협 속에서 소수의 귀환민들은 두려움에 시달림. 하나님의 축복 약속이 두려움을 이기는 힘", "목회적활용":"하나님의 약속이 두려움보다 크다. 약속을 붙잡으면 두려움이 물러간다"}
