        {"항목":"뉘우치지 않으심", "내용":"하나님이 심판 결정을 번복하지 않으셨다는 것은 심판의 확실성과 공의의 불변성을 의미", "목회적활용":"하나님의 심판은 임의적이 아니라 공의에 기반한 확고한 결정"},
        {"항목":"14-15절의 대비", "내용":"14절의 '재앙을 뜻하였다'와 15절의 '은혜를 뜻하였다'가 대조. 심판의 확실성만큼 은혜의 확실성도 강조", "목회적활용":"하나님이 심판에 확고하셨듯 은혜에도 확고하시다"}
