    표5_매튜헨리: [
        {"영어원문":"When your fathers provoked me to wrath, I thought to punish them and did not repent.", "한국어번역":"너희 조상이 내 노를 격발할 때 내가 그들을 벌하기로 뜻하고 뉘우치지 않았다.", "핵심통찰":"하나님의 심판은 확고하고 불변하다"},
        {"영어원문":"As God was resolute in punishing, so he will be resolute in rewarding their obedience.", "한국어번역":"하나님이 징벌에 확고하셨듯이 순종에 대한 보상에도 확고하실 것이다.", "핵심통찰":"심판의 확고함이 은혜의 확고함을 보증한다"},
        {"영어원문":"The same God that purposed evil against them for their sins now purposes good to them.", "한국어번역":"죄로 인해 재앙을 계획하셨던 그 하나님이 이제 그들에게 선을 계획하신다.", "핵심통찰":"동일한 하나님이 심판에서 은혜로 전환하신다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"재앙을 뜻하고 뉘우치지 않았으나 - 하나님의 확고한 공의", "예화_적용":"하나님의 심판은 임의적이 아니라 공의에 기반한 확고한 결정이다"},
        {"대지":"서론", "내용":"하나님은 과거의 심판을 상기시키신다. 열조가 노를 격발할 때 재앙을 뜻하시고 뉘우치지 않으셨다. 이 말씀은 무섭지만 동시에 15절의 은혜를 더욱 빛나게 한다. 심판에 확고하셨던 하나님이 은혜에도 확고하시기 때문이다", "예화_적용":"하나님의 심판의 확고함이 은혜의 확고함을 보증한다"},
        {"대지":"1대지: 노를 격발함 (인간의 책임)", "내용":"열조의 불순종이 하나님의 분노를 유발. 심판의 원인은 하나님이 아니라 인간의 죄", "예화_적용":"심판의 원인을 하나님께 돌리지 말라. 우리의 죄가 원인이다"},
        {"대지":"2대지: 재앙을 뜻하고 (하나님의 결정)", "내용":"하나님의 심판은 충동이 아니라 의도적 결정. 공의에 기반한 계획적 행위", "예화_적용":"하나님의 모든 행위에는 목적과 계획이 있다"},
        {"대지":"3대지: 뉘우치지 아니함 (확고한 공의)", "내용":"심판 결정을 번복하지 않으심. 하나님의 공의는 흔들리지 않는다", "예화_적용":"하나님의 공의를 가볍게 여기지 말라. 동시에 이 확고함이 은혜에도 적용됨을 기뻐하라"},
        {"대지":"결론", "내용":"심판에 확고하셨던 하나님이 15절에서 은혜에도 확고하시다고 선언하신다. 이것이 우리의 소망이다. 하나님의 성실하심은 심판에서도 은혜에서도 동일하다", "예화_적용":"하나님의 확고한 심판을 두려워하되, 확고한 은혜를 기뻐하라"}
    ],
