        {"영어원문":"This was fulfilled in the accession of many proselytes to the Jewish church, and more fully in the conversion of the Gentiles to Christ.", "한국어번역":"이것은 유대교로의 많은 개종자에서 성취되었고, 더 완전하게는 이방인의 그리스도에 대한 회심에서 성취되었다.", "핵심통찰":"궁극적 성취는 그리스도 안에서의 열방 구원"}
