        {"대지":"서론", "내용":"스가랴 8장의 마지막, 그리고 7-8장 전체의 절정이다. 열국의 열 명이 유다 사람 한 명의 옷자락을 잡고 말한다 - '하나님이 너희와 함께하심을 들었나니 우리도 함께 가겠다.' 이것이 전도의 궁극적 비전이다", "예화_적용":"사람들이 교회에 오는 이유는 프로그램이 아니라 '거기에 하나님이 계신다'는 증거"},
        {"대지":"1대지: 열 명이 한 명의 옷자락을 잡음 (압도적 반응)", "내용":"열(완전수) 대 일의 비율. 한 사람의 삶이 열 사람을 움직이는 영향력", "예화_적용":"한 사람의 진정한 신앙이 열 사람을 변화시킬 수 있다"},
        {"대지":"2대지: 하나님이 함께하심을 들었나니 (임재의 증거)", "내용":"이방인들이 유다인을 따르는 이유는 '하나님이 함께하심'. 임재가 최고의 전도", "예화_적용":"프로그램이나 시설이 아닌 하나님의 임재가 사람을 끌어당긴다"},
        {"대지":"3대지: 우리가 함께 가겠노라 (동행의 결단)", "내용":"이방인들의 자발적이고 열정적인 동행 결단", "예화_적용":"진정한 회심은 강제가 아니라 하나님의 임재에 끌려 자발적으로 오는 것"},
        {"대지":"결론", "내용":"7장의 금식 질문으로 시작된 말씀이 8장 23절의 웅장한 비전으로 마무리된다. 금식의 형식보다 하나님의 임재가 중요하다. 하나님이 함께하시는 삶을 살 때 세상이 달려온다", "예화_적용":"하나님의 임재가 함께하는 삶을 살라. 그것이 가장 강력한 전도이다"}
