        {"대지":"서론", "내용":"구약에서 가장 아름다운 메시아 예언 중 하나이다. 시온의 딸에게 크게 기뻐하라는 명령이 주어지고 그 이유가 선포된다. 네 왕이 온다! 그런데 이 왕은 세상의 기대와 완전히 다르다", "예화_적용":"하나님의 방법은 항상 우리의 기대를 뛰어넘는다"},
        {"대지":"1대지: 크게 기뻐하라 (메시아적 기쁨의 명령)", "내용":"기뻐함이 선택이 아니라 명령으로 주어짐. 메시아의 오심은 기뻐할 수밖에 없는 사건", "예화_적용":"메시아를 만난 기쁨은 환경을 초월하는 기쁨이다"},
        {"대지":"2대지: 공의로우며 구원을 베푸시는 왕 (의와 은혜의 조화)", "내용":"공의만 있으면 정죄뿐이고 은혜만 있으면 방종이 된다. 메시아는 둘을 완벽히 조화시키심", "예화_적용":"십자가는 공의와 사랑이 만나는 지점이다"},
        {"대지":"3대지: 겸손하여 나귀를 타시니 (역설적 왕권)", "내용":"전쟁 말이 아닌 평화의 나귀, 왕관이 아닌 겸손. 세상의 기대를 완전히 뒤집는 왕", "예화_적용":"우리도 세상의 방식이 아닌 하나님의 방식으로 살 수 있다"},
        {"대지":"결론", "내용":"나귀 타신 왕은 2천 년 전 예루살렘에 오셨다. 그분은 십자가에서 공의와 구원을 동시에 이루셨다. 이 왕 앞에 기뻐하며 무릎 꿇자", "예화_적용":"오늘도 겸손하게 우리에게 오시는 왕을 기쁨으로 맞이하라"}
