        {"대지":"2대지: 헬라 자식을 치게 함 (세상 권세와의 대결)", "내용":"세상 최강 문명 헬라에 대항하게 하심. 하나님이 승리를 주심", "예화_적용":"세상의 가치관과 타협하지 않고 하나님의 진리로 대항하라"},
        {"대지":"3대지: 용사의 칼 같게 하리라 (변화된 정체성)", "내용":"시온이 용사의 칼처럼 강력한 존재로 변화됨", "예화_적용":"하나님이 내 안에 역사하시면 나도 용사가 될 수 있다"},
        {"대지":"결론", "내용":"하나님은 우리를 무기로 사용하신다. 분열을 치유하시고 연합하게 하시며 강력한 도구로 만드신다. 하나님의 손에 쓰임받는 활과 화살이 되자", "예화_적용":"나는 하나님의 어떤 도구인가? 기꺼이 쓰임받는 삶을 살자"}
