        {"대지":"서론", "내용":"전쟁의 절정이다. 만군의 여호와가 직접 호위하시니 그 결과는 원수를 삼키는 완전한 승리이다. 그 승리의 기쁨은 제사적 축제가 된다", "예화_적용":"하나님이 함께하시면 전쟁의 결과는 이미 정해져 있다"},
        {"대지":"1대지: 만군의 여호와의 호위 (천군의 보호)", "내용":"만군의 주가 직접 방패가 되심. 천군천사의 통솔자가 직접 보호하심", "예화_적용":"가장 강한 보호는 인간의 방패가 아니라 하나님의 임재이다"},
        {"대지":"2대지: 원수를 삼키며 물매 돌을 밟음 (완전한 승리)", "내용":"원수를 삼키고 적의 무기를 밟는 압도적 승리", "예화_적용":"하나님 안에서 우리는 넉넉히 이기는 자이다 (롬 8:37)"},
        {"대지":"3대지: 피가 가득한 동이 (승리의 제사적 축제)", "내용":"전쟁의 승리가 하나님께 드리는 제사로 연결됨", "예화_적용":"모든 승리를 하나님께 돌리는 것이 참된 예배이다"},
        {"대지":"결론", "내용":"만군의 여호와가 우리 편이시다. 이 확신이 있으면 어떤 전쟁도 두렵지 않다. 승리의 기쁨으로 하나님께 예배를 드리자", "예화_적용":"오늘의 전쟁에서도 만군의 여호와의 호위를 기억하고 담대하라"}
