        {"대지":"3대지: 새 포도주의 기쁨 (충만한 기쁨)", "내용":"새 포도주는 기쁨과 축제의 상징. 메시아 왕국의 넘치는 기쁨", "예화_적용":"하나님의 나라는 기쁨이 넘치는 곳이다. 그 기쁨을 미리 누리라"},
        {"대지":"결론", "내용":"9장은 심판으로 시작하여 축복으로 끝난다. 이것이 하나님의 패턴이다. 아무리 어두운 심판의 시간도 궁극적으로는 풍성한 축복으로 마무리된다", "예화_적용":"지금의 어려움이 영원하지 않다. 하나님의 형통함과 아름다움을 기대하라"}
