        {"대지":"서론", "내용":"스가랴 10장은 강력한 명령으로 시작한다. 봄비 때에 여호와께 비를 구하라! 비를 주시는 분은 바알이 아니라 여호와이시다. 구하면 주시는 하나님의 은혜를 경험하라", "예화_적용":"축복의 원천은 오직 하나님이시다"},
        {"대지":"1대지: 봄비 때에 구하라 (적절한 시기의 기도)", "내용":"봄비는 수확 직전의 결정적 비. 때를 놓치면 수확이 없다", "예화_적용":"기도에도 때가 있다. 결정적 순간에 기도하라"},
        {"대지":"2대지: 번개를 내는 여호와 (자연의 주관자)", "내용":"번개와 비를 주시는 분은 여호와뿐. 바알 숭배에 대한 거부", "예화_적용":"축복의 원천을 바로 알아야 한다. 우상이 아닌 하나님께 구하라"},
        {"대지":"3대지: 각 사람에게 채소를 (개인적 돌봄)", "내용":"소낙비가 내려 각 사람에게 밭의 채소를 줌. 개별적 공급", "예화_적용":"하나님은 나 개인을 돌보신다. 일반적이 아닌 개인적 은혜를 경험하라"},
        {"대지":"결론", "내용":"비를 구하는 기도가 있어야 비가 내린다. 하나님이 주실 수 있으시지만 구하라 하신다. 봄비 같은 성령의 은혜를 사모하고 구하자", "예화_적용":"지금이 봄비를 구할 때이다. 간절히 기도하라"}
