        {"원어":"הָלַךְ (할라크)", "의미_문법":"왕래하다/걷다 - 동사 히트파엘형. 지속적 행보", "설교포인트":"하나님의 이름으로 살아가는 삶이 참된 행보이다"},
        {"원어":"שֵׁם (쉠)", "의미_문법":"이름 - 명사. 하나님의 본질과 권위", "설교포인트":"하나님의 이름을 받드는 것이 신앙 생활의 핵심이다"},
        {"원어":"נְאֻם (네움)", "의미_문법":"말씀/선언 - 명사. 예언적 선포", "설교포인트":"'여호와의 말이니라'는 약속의 확실성을 보증한다"}
