        {"대지":"서론", "내용":"스가랴 10장의 마지막 절은 전체 장의 결론이다. 봄비를 구하라로 시작한 장이 여호와를 의지하여 견고해지고 그 이름으로 왕래하는 삶으로 마무리된다. 이것이 하나님이 원하시는 삶이다", "예화_적용":"신앙의 최종 목표는 하나님을 의지하며 사는 것이다"},
        {"대지":"1대지: 여호와를 의지하여 (견고함의 원천)", "내용":"견고함이 자기 능력이 아닌 하나님 의지에서 옴", "예화_적용":"내 힘이 아닌 하나님의 힘으로 서는 것이 참된 견고함이다"},
        {"대지":"2대지: 내 이름을 받들어 왕래하리라 (일상의 신앙)", "내용":"특별한 순간이 아닌 매일의 왕래에서 하나님의 이름을 높임", "예화_적용":"예배당에서뿐 아니라 직장에서 가정에서 하나님의 이름으로 살라"},
        {"대지":"3대지: 여호와의 말이니라 (약속의 보증)", "내용":"이 모든 약속이 여호와의 말씀이므로 반드시 성취됨", "예화_적용":"하나님의 약속을 의심하지 말라. 말씀하신 분이 반드시 이루신다"},
        {"대지":"결론", "내용":"하나님을 의지하고 그 이름으로 살아가는 것. 이것이 10장이 우리에게 주는 최종 메시지이다. 드라빔이 아닌 여호와를, 자기 힘이 아닌 하나님의 힘을, 세상의 이름이 아닌 하나님의 이름을 선택하라", "예화_적용":"오늘 하루도 여호와를 의지하고 그 이름으로 왕래하라"}
