        {"구절":"마 21:13", "연결점":"내 집은 기도하는 집이라 하였거늘 강도의 소굴로 만듦", "구분":"신약"},
        {"구절":"마 23:23-28", "연결점":"외식하는 자들에 대한 예수님의 책망", "구분":"신약"},
        {"구절":"딤전 4:2", "연결점":"양심이 화인 맞은 자들", "구분":"신약"},
        {"구절":"요 9:41", "연결점":"너희가 보인다 하니 너희 죄가 그대로 있느니라", "구분":"신약"}
