        {"항목":"두 막대기", "내용":"고대 근동의 목자들은 막대기와 지팡이를 사용. 여기서 두 막대기는 하나님의 두 가지 돌봄의 방식을 상징", "목회적활용":"하나님의 돌봄에는 은혜와 연합이라는 두 차원이 있다"},
        {"항목":"은총과 연락", "내용":"은총은 하나님과 백성 사이의 은혜 관계, 연락은 유다와 이스라엘의 형제 연합을 상징. 두 축이 모두 필요", "목회적활용":"하나님과의 수직적 관계와 형제간의 수평적 관계가 모두 중요하다"}
