        {"항목":"상호 거부", "내용":"하나님이 그들을 싫어하시고 그들도 하나님을 미워함. 관계의 완전한 단절을 보여주는 비극적 상황", "목회적활용":"하나님과의 관계에서 상호 신뢰가 깨지면 회복이 어려워진다"}
