        {"상황":"지도자의 잘못된 행동에 실망한 분", "성경원리":"하나님도 불충한 목자들을 싫어하시고 심판하셨다", "실제적용":"사람에 대한 실망이 하나님에 대한 실망이 되지 않게 하라. 참된 목자는 그리스도이시다"},
        {"상황":"하나님과의 관계가 멀어진 분", "성경원리":"상호 거부는 작은 무관심에서 시작되어 완전한 단절로 이어졌다", "실제적용":"관계가 완전히 단절되기 전에 지금 돌아오라. 작은 순종부터 시작하라"}
