        {"대지":"2대지: 망하는 자는 망하는 대로 (멸망의 방치)", "내용":"사라지고 없어지는 것을 막지 않으심. 개인과 공동체의 존재 자체가 위협받음", "예화_적용":"하나님이 없으면 우리의 존재 자체가 지탱되지 않는다"},
        {"대지":"3대지: 피차 살을 먹음 (내부 파괴)", "내용":"남은 자들마저 서로를 파괴함. 공동체 내부의 분쟁과 자기 파괴", "예화_적용":"하나님 없는 공동체는 결국 서로를 잡아먹는다. 연합의 근원은 하나님이시다"},
        {"대지":"결론", "내용":"목자가 떠난 양떼의 비극은 하나님의 임재가 얼마나 소중한지를 역설적으로 보여준다. 하나님을 붙잡고 떠나지 않는 것이 생존의 길이다", "예화_적용":"하나님의 임재를 사모하고 붙잡으라. 그것이 생명의 길이다"}
