        {"영어원문":"When God breaks the staff of Beauty, the bands of Bands will soon be broken too.", "한국어번역":"하나님이 은총의 막대기를 자르시면 연락의 막대기도 곧 잘릴 것이다.", "핵심통찰":"하나님과의 관계가 깨지면 형제 관계도 깨진다"}
