    표2_역사적배경: [
        {"항목":"은 삼십", "내용":"출 21:32에 따르면 은 삼십은 노예의 값이다. 목자의 수고를 노예 한 명 값으로 평가한 것은 극도의 모욕이며 경멸의 표현", "목회적활용":"하나님의 사랑과 돌봄을 가볍게 여기는 것은 하나님을 모욕하는 것이다"},
        {"항목":"고가를 물어봄", "내용":"목자가 자신의 삯을 물어본 것은 백성의 마음을 시험하기 위한 것. 하나님은 강제로 사랑받기를 원하지 않으시고 자발적 반응을 기다리신다", "목회적활용":"하나님은 우리의 자발적 헌신과 감사를 원하신다"},
        {"항목":"메시아 예언", "내용":"이 구절은 유다가 예수를 은 삼십에 판 사건의 정확한 예언 (마 26:15). 약 500년 전의 예언이 정확히 성취됨", "목회적활용":"하나님의 예언은 하나도 빠짐없이 성취된다"}
    ],
    표3_신학적의미: [
        {"교리":"메시아의 가치 평가", "설명":"하나님의 목자(메시아)에 대한 백성의 평가가 은 삼십 곧 노예 한 명 값이라는 것은 인류가 하나님의 아들을 얼마나 경시했는지를 보여준다", "관련구절":"마 26:15, 사 53:3, 요 1:11, 빌 2:7"},
        {"교리":"자발적 평가의 중요성", "설명":"하나님은 '좋게 여기거든'이라고 하시며 강제하지 않으신다. 하나님은 인간의 자발적 반응을 존중하시되 그 결과에 대한 책임도 묻으신다", "관련구절":"수 24:15, 계 3:20, 요 6:67, 롬 10:9"},
        {"교리":"예언의 정확성", "설명":"은 삼십이라는 구체적 금액이 약 500년 후 정확히 성취됨. 이는 하나님 말씀의 초자연적 정확성을 증명한다", "관련구절":"마 26:15, 마 27:3-10, 벧후 1:21, 사 46:10"}
    ],
