        {"구분":"좋게 여기거든", "내용":"자발적 선택을 요구하시는 하나님", "그리스도연결":"너희도 가려느냐 묻으시며 자발적 따름을 원하신 그리스도 (요 6:67)"},
        {"구분":"노예의 값으로 평가됨", "내용":"하나님의 목자가 가장 낮은 값으로 취급됨", "그리스도연결":"종의 형체를 취하시고 자기를 낮추신 그리스도 (빌 2:7-8)"}
