    표6_설교자료: [
        {"대지":"제목", "내용":"은 삼십에 팔린 목자 - 하나님의 가치를 경시한 대가", "예화_적용":"우리는 하나님의 가치를 어떻게 평가하고 있는가?"},
        {"대지":"서론", "내용":"하나님의 목자가 자신의 삯을 물었을 때 백성은 은 삼십을 내놓았다. 이것은 노예 한 명의 값이다. 500년 후 유다가 정확히 은 삼십에 예수를 팔았다. 인류는 하나님의 아들을 노예 값으로 평가했다", "예화_적용":"세상이 그리스도를 어떻게 대했는지 돌아보라"},
        {"대지":"1대지: 좋게 여기거든 (자발적 선택의 기회)", "내용":"하나님은 강요하지 않으시고 자발적 반응을 기다리신다. 우리에게 선택의 자유를 주심", "예화_적용":"하나님의 은혜에 어떻게 반응하는지가 우리의 신앙을 보여준다"},
        {"대지":"2대지: 은 삼십 (노예의 값으로 평가된 목자)", "내용":"은 삼십은 노예 한 명의 값. 하나님의 목자를 이 가격으로 평가한 것은 극도의 모욕", "예화_적용":"우리의 삶에서 하나님을 가장 귀한 분으로 대하고 있는가?"},
        {"대지":"3대지: 예언의 성취 (500년 후 정확히 이루어짐)", "내용":"스가랴의 은 삼십 예언이 유다의 배신에서 정확히 성취됨. 하나님 말씀의 초자연적 정확성", "예화_적용":"하나님의 말씀은 하나도 땅에 떨어지지 않는다. 약속을 믿으라"},
        {"대지":"결론", "내용":"은 삼십에 팔린 그리스도는 그 값으로 우리를 사셨다. 노예의 값이 전 인류의 구원 값이 되었다. 이 놀라운 역전을 감사하며 그리스도의 참된 가치를 고백하자", "예화_적용":"세상이 경멸한 그 값이 우리의 구원이 되었다. 감사하며 살자"}
    ],
