        {"새찬송가":"149", "통일찬송가":"131", "제목":"만 왕의 왕 내 주께서", "선정이유":"왕이신 그리스도가 노예로 취급받으심"},
        {"새찬송가":"152", "통일찬송가":"136", "제목":"오 거룩하신 주님", "선정이유":"은 삼십에 팔리신 거룩하신 주님"},
        {"새찬송가":"248", "통일찬송가":"228", "제목":"십자가의 길", "선정이유":"배신과 고난의 길을 가신 그리스도"}
