        {"구절":"마 27:3", "연결점":"유다가 은 삼십을 가지고 대제사장들에게 돌려주며", "구분":"신약"},
        {"구절":"빌 2:7", "연결점":"종의 형체를 가지사 자기를 낮추시고", "구분":"신약"},
        {"구절":"요 1:11", "연결점":"자기 땅에 오매 자기 백성이 영접하지 아니하였으나", "구분":"신약"}
