        {"대지":"서론", "내용":"여호와께서 명하신대로 은 삼십을 토기장이에게 던졌다. 이 장면은 500년 후 예루살렘 성전에서 정확히 재현된다. 유다가 은 삼십을 성전에 던지고 대제사장들이 토기장이의 밭을 산 것이다", "예화_적용":"하나님의 예언의 정확성에 놀라움을 가지라"},
        {"대지":"1대지: 토기장이에게 던지라 (하나님의 주권적 처분)", "내용":"토기장이는 하나님의 주권을 상징. 경멸의 값을 주권적으로 처분하시는 하나님", "예화_적용":"하나님은 인간의 악한 행위도 주권적으로 다루신다"},
        {"대지":"2대지: 여호와의 전에서 (성전에서 시작되는 심판)", "내용":"가장 거룩한 곳에서 심판이 선포됨. 하나님의 집에서부터 심판이 시작됨", "예화_적용":"하나님의 심판은 밖이 아닌 안에서부터 시작된다"},
        {"대지":"3대지: 예언의 정확한 성취 (은 삼십과 유다의 배신)", "내용":"은 삼십, 성전, 토기장이라는 세 요소가 마태복음에서 정확히 성취됨", "예화_적용":"하나님의 말씀은 한 글자도 빠지지 않고 이루어진다. 약속을 믿으라"},
        {"대지":"결론", "내용":"토기장이에게 던져진 은 삼십은 인간의 죄와 하나님의 주권이 만나는 지점이다. 인간은 하나님을 경시했지만 하나님은 그 경시조차 구원의 계획 안에서 사용하셨다", "예화_적용":"하나님의 구원 계획은 인간의 악조차 넘어서는 놀라운 것이다"}
