        {"구절":"시 133:1", "연결점":"형제가 연합하여 동거함이 어찌 그리 선하고 아름다운고", "구분":"구약"},
        {"구절":"암 1:11", "연결점":"칼로 그의 형제를 쫓아 긍휼을 버렸음이라", "구분":"구약"},
        {"구절":"겔 37:22", "연결점":"그 땅에서 한 나라가 되게 하리라 다시는 두 나라가 되지 아니하며", "구분":"구약"},
        {"구절":"요 17:21", "연결점":"아버지여 그들이 다 하나가 되게 하옵소서", "구분":"신약"},
        {"구절":"엡 2:14", "연결점":"그는 우리의 화평이신지라 둘로 하나를 만드사", "구분":"신약"},
        {"구절":"고전 1:10", "연결점":"다 같은 말을 하고 너희 가운데 분쟁이 없이 같은 마음과 같은 뜻으로 온전히 합하라", "구분":"신약"},
        {"구절":"요 13:34-35", "연결점":"새 계명을 너희에게 주노니 서로 사랑하라", "구분":"신약"}
