        {"대지":"서론", "내용":"스가랴 11장의 마지막은 못된 목자에 대한 저주 선언이다. 양떼를 버리고 착취한 목자의 팔이 마르고 눈이 어두워진다. 힘과 분별력을 모두 잃는 완전한 심판이다", "예화_적용":"악한 권력의 최후는 예외 없이 비참하다"},
        {"대지":"1대지: 화 있을찐저 (하나님의 저주 선언)", "내용":"호이(화 있을찐저)는 성경에서 가장 강한 저주의 표현. 하나님이 직접 선포하시는 심판", "예화_적용":"하나님의 화를 자초하지 않도록 경성하라"},
        {"대지":"2대지: 팔이 마름 (권력의 상실)", "내용":"힘과 권력을 상징하는 팔이 완전히 마름. 착취에 사용한 힘이 무력해짐", "예화_적용":"하나님을 거역하여 얻은 힘은 반드시 마른다"},
        {"대지":"3대지: 오른 눈이 어두워짐 (분별력의 상실)", "내용":"전투에서 가장 중요한 오른 눈이 어두워짐. 비전과 분별력의 완전한 상실", "예화_적용":"영적 분별력을 잃으면 모든 것을 잃는다. 말씀으로 눈을 밝히라"},
        {"대지":"결론", "내용":"못된 목자의 비참한 최후는 모든 거짓 지도자에 대한 경고이다. 동시에 참된 목자 그리스도의 영원한 통치를 소망하게 한다. 우리의 참 목자는 팔이 마르지 않고 눈이 어둡지 않으신 전능하시고 전지하신 분이다", "예화_적용":"참된 목자 그리스도의 능력과 지혜를 의지하라"}
