        {"영어원문":"He who stretcheth forth the heavens, layeth the foundation of the earth, and formeth the spirit of man—this is He who speaks.", "한국어번역":"하늘을 펴시고 땅의 기초를 놓으시고 사람의 심령을 지으시는 분—이 분이 말씀하신다.", "핵심통찰":"말씀하시는 분의 정체가 말씀의 권위를 보증한다"},
        {"영어원문":"God is the Father of spirits as well as the Former of bodies; He has access to and authority over the inner man.", "한국어번역":"하나님은 몸의 창조자이실 뿐 아니라 영의 아버지이시다. 그분은 내면의 사람에 대한 접근과 권위를 가지신다.", "핵심통찰":"하나님은 우리의 마음에 접근하시고 다스리시는 분이다"}
