        {"대지":"2대지: 땅의 터를 세우신 하나님 (확실한 기초)", "내용":"땅의 기초를 놓으신 것처럼 하나님의 약속에는 확실한 기초가 있다", "예화_적용":"하나님의 약속은 반석 위에 세워진 견고한 기초이다"},
        {"대지":"3대지: 심령을 지으신 하나님 (내면의 주인)", "내용":"인간의 영을 형성하신 하나님. 가장 깊은 내면까지 아시고 다스리시는 분", "예화_적용":"하나님은 우리의 마음을 아시고 변화시키실 수 있는 유일한 분이다"},
        {"대지":"결론", "내용":"하늘과 땅과 심령을 지으신 하나님이 말씀하신다. 이 선포는 반드시 이루어진다. 창조주의 약속 위에 우리의 소망을 세우자", "예화_적용":"창조주의 권위에 기초한 약속을 붙잡으라"}
