        {"항목":"유다를 눈을 들어 돌아봄", "내용":"열방의 말은 눈이 멀게 하시면서 유다에게는 눈을 열어 돌아보시는 대조. 심판과 구원이 동시에 일어남", "목회적활용":"같은 사건이 누구에게는 심판이 되고 누구에게는 구원이 된다"},
        {"항목":"눈 멂의 심판", "내용":"신 28:28에 불순종의 저주로 예고된 눈 멂이 이스라엘의 대적에게 적용됨. 열방의 공격 능력을 완전히 상실시킴", "목회적활용":"하나님의 심판은 적의 능력을 근본적으로 제거하신다"}
