        {"교리":"적의 무력화", "설명":"말을 놀라게 하고 기수를 미치게 하고 눈을 멀게 하시는 삼중 무력화. 하나님이 적의 능력을 근본적으로 제거하심", "관련구절":"왕하 6:18, 출 14:25, 삿 7:22, 삼하 17:14"},
        {"교리":"하나님의 돌아보심", "설명":"눈을 들어 돌아보신다는 것은 하나님의 적극적 관심과 보호를 의미. 하나님이 자기 백성을 잊지 않으시고 주목하심", "관련구절":"시 33:18, 시 34:15, 벧전 3:12, 시 121:4"}
