        {"구분":"영광의 균형", "내용":"한쪽이 다른 쪽보다 크지 않게 하심", "그리스도연결":"지체가 서로 같은 영광을 받는 그리스도의 몸 (고전 12:22-25)"},
        {"구분":"장막을 먼저 돌봄", "내용":"가장 취약한 곳에 먼저 손길이 닿음", "그리스도연결":"말구유에서 나시고 가장 낮은 곳에 오신 그리스도 (눅 2:7, 빌 2:6-8)"}
