    표2_역사적배경: [
        {"항목":"약한 자가 다윗 같음", "내용":"가장 약한 거민도 골리앗을 죽인 다윗처럼 강해진다는 약속. 하나님의 보호 안에서 일어나는 초자연적 능력 부여", "목회적활용":"하나님 안에서는 약한 자도 영웅이 될 수 있다"},
        {"항목":"다윗 족속이 하나님 같음", "내용":"다윗 왕가가 하나님 같은 존재가 된다는 극적 표현. 메시아적 왕조의 초자연적 성격을 예시", "목회적활용":"하나님이 부여하시는 권위는 인간의 한계를 초월한다"},
        {"항목":"여호와의 사자 같음", "내용":"여호와의 사자(말악 여호와)는 구약에서 하나님의 현현으로 이해됨. 다윗 족속이 백성을 인도하는 하나님의 대리인이 됨", "목회적활용":"하나님이 세우신 지도자는 하나님의 권위를 대리한다"}
    ],
    표3_신학적의미: [
        {"교리":"약함의 변환", "설명":"하나님의 보호 아래서 약한 자가 다윗 같이 강해지고, 다윗은 하나님 같이 되는 단계적 역전. 이는 하나님의 능력이 인간의 약함을 통해 나타남", "관련구절":"고후 12:10, 사 40:29-31, 욜 3:10, 빌 4:13"},
        {"교리":"신격화가 아닌 능력 부여", "설명":"하나님 같다는 표현은 존재론적 신격화가 아니라 기능적 능력 부여. 하나님의 능력을 위임받아 행사하는 것", "관련구절":"출 7:1, 시 82:6, 요 10:34-35, 삼하 14:17"},
        {"교리":"여호와의 사자 그리스도론", "설명":"여호와의 사자는 구약의 그리스도 현현(Christophany)으로 이해됨. 다윗 족속이 이 사자 같다 함은 메시아적 통치의 예표", "관련구절":"출 23:20-21, 삿 13:18, 사 63:9, 말 3:1"}
    ],
