        {"항목":"찌른 바 그를 바라봄", "내용":"이스라엘이 자신들이 찌른 자를 바라보는 순간. 이것은 메시아 예수 그리스도의 십자가 사건을 가리키는 가장 명확한 구약 예언 중 하나", "목회적활용":"십자가를 바라보는 것이 참된 회개의 시작이다"},
        {"항목":"독자를 위한 애통", "내용":"고대 근동에서 독자의 죽음은 가문의 소멸을 의미하는 최대의 비극. 이 정도의 깊은 애통으로 회개한다는 표현", "목회적활용":"진정한 회개는 가벼운 것이 아니라 깊은 슬픔과 애통이다"},
        {"항목":"은총과 간구의 영", "내용":"회개가 인간의 노력이 아닌 하나님이 부어주시는 영에서 시작됨. 은혜가 먼저이고 회개가 따라옴", "목회적활용":"회개할 수 있는 것 자체가 하나님의 은혜이다"}
