        {"교리":"메시아의 찔림", "설명":"이스라엘이 찌른 자가 메시아이며 이것이 예수 그리스도의 십자가를 예언. 요 19:37에서 이 구절이 직접 인용됨", "관련구절":"요 19:37, 사 53:5, 시 22:16, 계 1:7"},
        {"교리":"민족적 회개", "설명":"다윗의 집과 예루살렘 전체의 집단적 회개. 이스라엘이 메시아를 인식하고 돌아오는 미래의 사건을 예고", "관련구절":"롬 11:26-27, 호 5:15, 렘 31:31-34, 겔 36:26-27"}
