        {"영어원문":"I will pour upon the house of David the spirit of grace and supplications—repentance begins with grace, not human effort.", "한국어번역":"내가 다윗의 집에 은총과 간구의 영을 부어주리라—회개는 인간의 노력이 아닌 은혜에서 시작된다.", "핵심통찰":"회개의 능력은 하나님이 부어주시는 은총에서 온다"},
        {"영어원문":"They shall look upon me whom they have pierced—a remarkable prophecy of Christ's crucifixion.", "한국어번역":"그들이 그 찌른 바 나를 바라보리라—그리스도의 십자가에 대한 놀라운 예언이다.", "핵심통찰":"십자가를 바라보는 것이 참된 회개의 시작이다"},
        {"영어원문":"They shall mourn as one that mourneth for his only son—true repentance is deep, personal, and heartfelt.", "한국어번역":"독자를 위하여 애통하듯 애통하리라—참된 회개는 깊고 개인적이며 진심에서 우러나온다.", "핵심통찰":"참된 회개는 형식이 아닌 깊은 마음의 슬픔이다"}
