        {"대지":"2대지: 찌른 바 그를 바라봄 (십자가 응시)", "내용":"자신들이 찌른 메시아를 바라보는 순간의 충격과 깨달음. 내 죄가 그를 찔렀다", "예화_적용":"십자가는 나의 죄가 하나님의 아들을 죽였다는 고백이다"},
        {"대지":"3대지: 독자를 위한 애통 (깊은 회개의 슬픔)", "내용":"독자를 잃은 것 같은 깊은 애통으로 회개함. 가벼운 후회가 아닌 진정한 통회", "예화_적용":"참된 회개는 마음이 찢어지는 것이다. 형식적 회개에 머물지 말라"},
        {"대지":"결론", "내용":"십자가를 바라보고 우리의 죄를 깨닫고 독자를 위한 애통처럼 깊이 회개하는 것. 이것이 구원의 길이다. 오늘 십자가를 바라보라. 그리고 깊이 회개하라", "예화_적용":"지금 십자가를 바라보라. 거기서 은혜와 회개가 시작된다"}
