        {"영어원문":"The greatest mourning in Israel's history becomes the model for their future repentance.", "한국어번역":"이스라엘 역사에서 가장 큰 애통이 미래의 회개의 모델이 된다.", "핵심통찰":"역사적 비극의 기억이 영적 회개의 깊이를 더한다"},
        {"영어원문":"True repentance is not superficial but reaches to the very depths of the heart.", "한국어번역":"참된 회개는 피상적이지 않고 마음의 깊은 곳까지 미친다.", "핵심통찰":"참된 회개는 마음 깊은 곳에서 우러나온다"}
