        {"대지":"1대지: 큰 애통 (회개의 깊이)", "내용":"피상적 후회가 아닌 온 도시가 울부짖는 큰 애통. 참된 회개의 깊이", "예화_적용":"형식적 회개에서 벗어나 마음 깊은 곳에서의 통회를 경험하라"},
        {"대지":"2대지: 하다드림몬의 애통 (역사적 모델)", "내용":"요시야 왕의 죽음에 대한 국가적 슬픔이 회개의 모델. 가장 선한 것을 잃은 슬픔", "예화_적용":"우리가 잃어버린 것이 얼마나 소중한지 깨달을 때 진정한 회개가 시작된다"},
        {"대지":"3대지: 므깃도 골짜기 (결정적 장소)", "내용":"역사적 전환점이 된 전쟁터에서 영적 전환점이 되는 회개가 일어남", "예화_적용":"하나님은 우리 인생의 결정적 순간에 회개의 기회를 주신다"},
        {"대지":"결론", "내용":"므깃도의 애통처럼 깊은 회개가 예루살렘을 변화시킬 것이다. 오늘 우리도 형식이 아닌 깊은 마음에서의 회개를 경험하자. 애통하는 자에게 위로가 있다", "예화_적용":"깊이 울 수 있는 자만이 참된 위로를 받는다"}
