        {"대지":"서론", "내용":"온 땅이 회개하되 각 족속이 따로 한다. 다윗 족속, 나단 족속, 남자와 여자 모두 따로 하나님 앞에 선다. 군중 속에 숨을 수 없는 회개, 각자의 몫인 회개가 있다", "예화_적용":"회개는 다른 사람 뒤에 숨을 수 없는 개인적 행위이다"},
        {"대지":"1대지: 각 족속이 따로 (개인적 회개)", "내용":"공동체 회개이지만 각자가 따로 하나님 앞에 섬. 군중심리가 아닌 진정한 개인적 결단", "예화_적용":"다른 사람의 회개에 묻어가지 말라. 나만의 회개가 필요하다"},
        {"대지":"2대지: 다윗과 나단의 족속 (지도층의 회개)", "내용":"왕가와 선지자 가문이 먼저 회개함. 지위가 높을수록 회개의 책임이 크다", "예화_적용":"지도자가 먼저 회개할 때 공동체가 따라온다"},
        {"대지":"3대지: 아내들이 따로 (가장 가까운 관계에서도 개별적)", "내용":"부부라도 따로 회개함. 가장 친밀한 관계도 회개를 대신할 수 없다", "예화_적용":"회개는 오직 나와 하나님 사이의 개인적 일이다"},
        {"대지":"결론", "내용":"진정한 회개는 공동체 전체의 것이면서 동시에 각 개인의 것이다. 오늘 나 혼자 하나님 앞에 서서 내 죄를 고백하자. 아무도 나를 대신할 수 없다", "예화_적용":"지금 하나님 앞에 홀로 서라. 그것이 회개의 시작이다"}
