        {"항목":"네 족속의 구성", "내용":"왕가(다윗), 선지자(나단), 제사장(레위), 소지파(시므이)의 네 족속은 이스라엘 사회 전체를 대표. 사회의 모든 계층이 회개에 참여", "목회적활용":"사회의 어떤 계층도 회개의 필요에서 제외되지 않는다"}
