        {"교리":"보편적 회개의 완결", "설명":"네 족속의 구체적 열거 후 '남은 모든 족속'으로 마무리함으로써 예외 없는 보편적 회개를 선언. 이스라엘 전체의 영적 변혁", "관련구절":"롬 11:26, 행 17:30, 빌 2:10-11, 계 5:13"},
        {"교리":"개인성의 최종 강조", "설명":"마지막 절에서도 '따로'가 반복됨. 보편적 회개이지만 그 안에서 개인적 결단이 핵심임을 최종 확인", "관련구절":"마 7:21, 롬 14:12, 계 20:12-13, 빌 2:12"},
        {"교리":"하나님의 포괄적 은혜", "설명":"남은 모든 족속까지 은총의 영이 미침. 하나님의 은혜는 어떤 족속도 빠뜨리지 않는 포괄적인 것", "관련구절":"딛 2:11, 벧후 3:9, 겔 18:32, 딤전 2:4"}
