        {"구분":"아내들도 따로", "내용":"마지막까지 남녀 개별 회개 강조", "그리스도연결":"각 사람이 자기 행한 대로 받는 심판 (계 20:12-13)"},
        {"구분":"예외 없는 보편성", "내용":"단 하나의 족속도 빠지지 않는 완전한 회개", "그리스도연결":"모든 사람이 구원 받기를 원하시는 하나님 (딤전 2:4)"}
