    표5_매튜헨리: [
        {"영어원문":"All the families that remain—not one family, not one individual, shall be exempt from this great mourning.", "한국어번역":"남은 모든 족속—단 하나의 가문도, 단 한 명의 개인도 이 큰 애통에서 면제되지 않을 것이다.", "핵심통찰":"회개에서 면제되는 자는 단 한 사람도 없다"},
        {"영어원문":"The chapter concludes with the universality and individuality of repentance—all must mourn, and each must mourn apart.", "한국어번역":"이 장은 회개의 보편성과 개인성으로 결론짓는다—모두가 애통해야 하고 각자 따로 애통해야 한다.", "핵심통찰":"회개는 보편적이면서 동시에 개인적이다"},
        {"영어원문":"This is the grace of God—that He extends the spirit of repentance to every family, leaving none without hope.", "한국어번역":"이것이 하나님의 은혜이다—회개의 영을 모든 족속에게 미치시어 소망 없는 자가 없게 하신다.", "핵심통찰":"모든 족속에게 미치는 회개의 영이 하나님의 은혜이다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"남은 모든 족속도 따로 - 회개의 완전한 범위", "예화_적용":"하나님의 회개의 부르심에서 제외되는 자는 없다"},
        {"대지":"서론", "내용":"스가랴 12장의 마지막 절은 간결하지만 강력하다. 다윗, 나단, 레위, 시므이 외에 남은 모든 족속도 각각 따로 회개한다. 예외 없는 보편적이고 개인적인 회개로 12장이 마무리된다", "예화_적용":"하나님은 마지막 한 사람까지 포기하지 않으신다"},
        {"대지":"1대지: 남은 족속 (누구도 빠지지 않음)", "내용":"구체적으로 열거되지 않은 모든 족속까지 포함. 하나님의 은혜는 빈틈없이 모두에게 미침", "예화_적용":"당신도 포함되어 있다. 하나님의 회개의 부르심에서 제외된 사람은 없다"},
        {"대지":"2대지: 각각 따로 (개인성의 최종 강조)", "내용":"마지막 절에서도 '따로'가 반복됨. 개인적 회개가 끝까지 강조됨", "예화_적용":"회개는 내가 직접 해야 하는 가장 개인적인 신앙 행위이다"},
        {"대지":"3대지: 아내들이 따로 (성별을 초월한 보편성)", "내용":"남녀 모두 각자 하나님 앞에 섬. 어떤 조건도 회개를 대신할 수 없음", "예화_적용":"하나님 앞에서의 회개에 대리는 없다. 각자의 몫이다"},
        {"대지":"결론", "내용":"12장은 하나님의 은총으로 시작된 회개가 온 이스라엘을 덮는 장면으로 끝난다. 왕에서 작은 씨족까지, 남녀노소 모두가 하나님 앞에 선다. 오늘 이 부르심이 우리에게도 임한다. 각자 따로 하나님 앞에 서자", "예화_적용":"지금 이 순간 하나님 앞에 홀로 서라. 그것이 은혜의 시작이다"}
    ],
