        {"새찬송가":"330", "통일찬송가":"278", "제목":"나 같은 죄인 살리신", "선정이유":"보편적 은혜와 개인적 구원"},
        {"새찬송가":"310", "통일찬송가":"273", "제목":"아 하나님의 은혜로", "선정이유":"모든 족속에게 미치는 하나님의 은혜"},
        {"새찬송가":"461", "통일찬송가":"388", "제목":"오 신실하신 주", "선정이유":"모든 사람을 향한 하나님의 신실한 사랑"}
