        {"구절":"벧후 3:9", "연결점":"아무도 멸망하지 아니하고 다 회개하기에 이르기를 원하시느니라", "구분":"신약"},
        {"구절":"롬 11:26", "연결점":"이와 같이 온 이스라엘이 구원을 받으리라", "구분":"구약"},
        {"구절":"겔 18:32", "연결점":"죽는 자의 죽는 것을 기뻐하지 아니하노라 그러므로 너희는 돌이켜 살지니라", "구분":"구약"},
        {"구절":"딛 2:11", "연결점":"모든 사람에게 구원을 주시는 하나님의 은혜가 나타나", "구분":"신약"},
        {"구절":"계 20:12", "연결점":"죽은 자들이 각각 자기의 행한 대로 심판을 받으니", "구분":"신약"}
