        {"대지":"서론", "내용":"죄 씻는 샘이 열린 후(1절) 하나님은 우상의 이름을 끊고 거짓 선지자와 더러운 귀신을 제거하신다. 정결의 은혜가 개인에서 사회 전체로 확대된다", "예화_적용":"개인의 정결이 사회의 정결로 이어진다"},
        {"대지":"1대지: 우상의 이름을 끊음 (대상의 제거)", "내용":"우상 자체와 그 이름과 기억까지 완전히 제거. 영적 오염의 대상을 완전히 없앰", "예화_적용":"삶에서 하나님의 자리를 차지하는 우상을 완전히 제거하라"},
        {"대지":"2대지: 거짓 선지자 제거 (매개의 차단)", "내용":"우상 숭배를 가르치고 전파하는 거짓 선지자를 제거. 거짓의 매개를 차단", "예화_적용":"거짓 가르침을 분별하고 참된 말씀만 따르라"},
        {"대지":"3대지: 더러운 귀신 추방 (근원의 제거)", "내용":"우상과 거짓 예언 뒤의 영적 세력까지 제거. 문제의 근원을 다룸", "예화_적용":"눈에 보이는 문제 뒤의 영적 근원을 하나님께 맡기라"},
        {"대지":"결론", "내용":"하나님의 정화는 대상(우상), 매개(거짓 선지자), 근원(악령)을 모두 다루는 완전한 것이다. 우리 삶에서도 이 삼중 정화를 경험하자", "예화_적용":"완전한 정결을 위해 대상과 매개와 근원을 모두 다루라"}
