        {"원어":"יֹלְדָיו (욜다우)", "의미_문법":"그를 낳은 자들 - 분사+접미사. 부모", "설교포인트":"진리를 위해서는 가장 가까운 관계도 넘어서야 한다"},
        {"원어":"וּדְקָרֻהוּ (우데카루후)", "의미_문법":"그를 찌르다 - 동사+접미사. 창으로 찌름", "설교포인트":"거짓 예언에 대한 무관용 원칙"}
