        {"대지":"서론", "내용":"충격적인 장면이다. 부모가 거짓 예언하는 자녀를 찌른다. 이것은 하나님의 진리가 어떤 인간 관계보다 우선해야 함을 극적으로 보여준다. 하나님의 이름을 빙자한 거짓은 용납될 수 없다", "예화_적용":"하나님의 이름으로 거짓을 말하는 것은 가장 심각한 범죄이다"},
        {"대지":"1대지: 여호와의 이름을 빙자함 (최악의 거짓)", "내용":"하나님의 권위를 도용하여 거짓을 말하는 것. 하나님의 이름으로 자기 의견을 전하는 위험", "예화_적용":"하나님이 말씀하지 않은 것을 하나님의 이름으로 말하지 말라"},
        {"대지":"2대지: 부모가 찌름 (진리 우선의 결단)", "내용":"가장 가까운 혈연관계도 하나님의 진리 앞에서 양보. 비정한 것이 아니라 거룩한 결단", "예화_적용":"하나님의 진리를 위해 때로는 어려운 결단을 해야 할 때가 있다"},
        {"대지":"3대지: 거짓 예언의 근절 (정결한 공동체)", "내용":"공동체 전체가 거짓에 무관용 태도를 취하는 거룩한 사회의 모습", "예화_적용":"교회는 진리를 수호하는 공동체여야 한다. 거짓 가르침에 타협하지 말라"},
        {"대지":"결론", "내용":"이 말씀은 우리에게 진리의 우선성을 가르친다. 인간 관계도 소중하지만 하나님의 진리가 최우선이다. 진리 위에 모든 관계를 세울 때 진정한 사랑이 가능하다", "예화_적용":"진정한 사랑은 진리 안에서만 완성된다. 진리 위에 관계를 세우라"}
