        {"상황":"진리와 관계 사이에서 갈등하는 분", "성경원리":"부모도 하나님의 진리를 위해 어려운 결단을 했다", "실제적용":"관계를 위해 진리를 양보하지 말라. 진리 안에서 세워진 관계만이 진정한 관계이다"}
