        {"대지":"서론", "내용":"거짓 선지자가 더 이상 자신을 선지자라 주장하지 못하고 '나는 농부'라고 말한다. 하나님의 부르심이 아닌 사람의 만듦으로 된 사역이 진리 앞에서 무너지는 장면이다", "예화_적용":"참된 소명이 없는 사역은 시간이 지나면 드러난다"},
        {"대지":"1대지: 나는 선지자가 아니라 (거짓 정체의 부인)", "내용":"그동안 선지자로 행세했지만 진리 앞에서 자기를 부인함. 거짓의 자기 폭로", "예화_적용":"진리는 결국 모든 거짓을 폭로한다. 처음부터 정직하게 살라"},
        {"대지":"2대지: 나는 농부라 (본래 자리로의 복귀)", "내용":"거짓 지위를 버리고 본래의 낮은 자리로 돌아감. 겸손의 회복", "예화_적용":"자신의 진짜 자리를 아는 것이 지혜이다. 분수를 알라"},
        {"대지":"3대지: 사람이 나를 부림 (인간적 사역의 한계)", "내용":"하나님이 아닌 사람이 만든 사역의 한계. 참된 소명과 인간적 소명의 차이", "예화_적용":"사역의 근거가 하나님의 부르심인지 인간의 만듦인지 점검하라"},
        {"대지":"결론", "내용":"참된 소명은 하나님에게서 온다. 사람이 만든 소명은 진리 앞에 무너진다. 오늘 나의 사역과 삶의 근거가 무엇인지 점검하자. 하나님의 부르심 위에 서야 흔들리지 않는다", "예화_적용":"하나님의 부르심 위에 서라. 그것만이 흔들리지 않는 기초이다"}
