        {"새찬송가":"391", "통일찬송가":"295", "제목":"지금까지 지내온 것", "선정이유":"과거에 싸워주신 하나님에 대한 감사"},
        {"새찬송가":"453", "통일찬송가":"370", "제목":"나의 생명 드리니", "선정이유":"하나님께 전적으로 맡기는 헌신"}
