        {"항목":"여호와의 날의 독특성", "내용":"이 날은 낮도 밤도 아닌 독특한 날. 창조 질서의 낮과 밤의 구분이 사라지는 초자연적인 날. 인간의 경험으로 이해할 수 없는 하나님만의 날", "목회적활용":"하나님의 일하심은 우리의 이해를 초월함을 인정하라"},
        {"항목":"어두워 갈 때의 빛", "내용":"저녁이 되어 어두워져야 할 때에 오히려 빛이 있음. 자연법칙을 넘어서는 초자연적 현상. 출애굽 때 이스라엘에게만 빛이 있었던 것과 유사", "목회적활용":"가장 어두운 때에 하나님의 빛이 비춤을 기대하라"},
        {"항목":"여호와만 아시는 때", "내용":"이 날의 정확한 시점은 여호와만 아심. 마 24:36 '그 날과 그 때는 아무도 모르나니 아버지만 아시느니라'와 일치", "목회적활용":"때를 알려 하지 말고 준비된 삶을 살라"}
