        {"교리":"악의 자멸적 본질", "설명":"악은 궁극적으로 자멸적이다. 서로 연합하여 하나님을 대적하지만 결국 서로를 파멸시킴. 악의 연합은 내부적으로 불안정", "관련구절":"시 7:15-16, 잠 26:27, 에 7:10, 시 9:15-16"},
        {"교리":"무전투 승리", "설명":"이스라엘이 싸우지 않고 승리함. 하나님이 적들을 혼란시켜 자멸하게 하므로 하나님의 백성은 서서 구원을 봄", "관련구절":"출 14:13-14, 대하 20:17, 시 46:10, 사 30:15"}
