        {"항목":"전리품의 신학적 의미", "내용":"출애굽 때 이스라엘이 애굽의 금은 패물을 가지고 나온 것(출 12:35-36)과 같은 패턴. 하나님의 구원에는 물질적 축복도 포함됨", "목회적활용":"하나님의 구원은 영적 축복뿐 아니라 실질적 회복도 포함"}
