        {"상황":"다문화 사회에서 갈등을 겪는 분", "성경원리":"모든 열국이 함께 여호와를 경배하며 초막절을 지킨다. 다양한 민족이 하나님 안에서 하나", "실제적용":"문화적 차이를 넘어 그리스도 안에서의 하나됨을 추구하라. 다양성은 하나님 나라의 풍성함이다"}
