        {"항목":"초막절의 보편화", "내용":"이스라엘의 민족 절기였던 초막절이 전 세계적 축제가 됨. 이방인도 참여해야 하는 보편적 경배의 날로 변화", "목회적활용":"복음은 한 민족을 넘어 온 세계를 위한 것"},
        {"항목":"벌의 확실성", "내용":"'이러하니라'는 확정적 선언. 불순종에 대한 벌이 확실하고 변경 불가능함을 강조", "목회적활용":"하나님의 말씀은 변하지 않으며 반드시 성취됨"}
