        {"대지":"2대지: 솥이 주발과 같음 (일상의 거룩함)", "내용":"부엌의 솥이 제단의 주발과 동등하게 됨. 일상의 평범한 행위가 성전의 제사와 같음", "예화_적용":"밥을 짓는 것도, 빨래를 하는 것도 하나님께 드리는 마음으로 하면 예배가 된다"},
        {"대지":"3대지: 여호와께 성결이라 (보편적 성결의 비전)", "내용":"대제사장만의 특권이 모든 것으로 확대됨. 만인 제사장직의 완전한 실현", "예화_적용":"우리 모두가 제사장이다. 삶 전체를 하나님께 드리는 거룩한 제사장의 삶을 살자"},
        {"대지":"결론", "내용":"하나님의 최종 비전은 삶 전체의 성결이다. 교회 안에서만 거룩하고 밖에서는 세속적인 이중생활이 아닌 24시간 365일 여호와께 성결한 삶. 이것이 우리의 목표이다", "예화_적용":"먹든지 마시든지 무엇을 하든지 하나님의 영광을 위하여 하라 (고전 10:31)"}
